// Survival Rates — Comparison, route: jsx
// Source: cancer-survival-rates_2
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

/** One row per condition, holding one survival percentage per step, in `steps` order. */
export type Data = {
  steps: string[];
  conditions: { name: string; values: number[] }[];
};

const STEPS = ['5 Year', '10 Year', '15 Year', '20 Year'];

/**
 * Fictional conditions with invented figures. Real condition names paired with invented
 * survival numbers would read as a medical claim, so neither half is real here.
 */
const SURVIVAL = [
  { name: 'Condition A', values: [99, 95, 88, 80] },
  { name: 'Condition B', values: [96, 96, 94, 95] },
  { name: 'Condition C', values: [95, 94, 91, 88] },
  { name: 'Condition D', values: [89, 85, 82, 79] },
  { name: 'Condition E', values: [86, 78, 71, 65] },
  { name: 'Condition F', values: [85, 80, 78, 74] },
  { name: 'Condition G', values: [84, 83, 81, 79] },
  { name: 'Condition H', values: [82, 76, 70, 65] },
  { name: 'Condition I', values: [71, 64, 63, 60] },
  { name: 'Condition J', values: [69, 56, 46, 38] },
  { name: 'Condition K', values: [62, 54, 50, 47] },
  { name: 'Condition L', values: [43, 32, 30, 26] }
];

const DEMO: Data = { steps: STEPS, conditions: SURVIVAL };

const CAPTION = 'Illustrative synthetic data. Fictional conditions, invented figures, not real survival statistics.';
const MARGIN = { top: 46, right: 106, bottom: 34, left: 106 };
const LABEL_GAP = 4;
const SEPARATION = 12;
const NAME_LABEL_MIN_WIDTH = 560;

const formatValue = d3.format('.0f');

/**
 * Iterative dodge: nudge overlapping label positions apart in place until every
 * neighbouring pair clears `separation`. Pure, so it can run inside useMemo.
 */
function dodge(positions: number[], separation = SEPARATION, maxIterations = 12): number[] {
  const spread = positions.slice();
  if (spread.length < 2) return spread;
  const order = d3.range(spread.length);
  for (let iteration = 0; iteration < maxIterations; iteration++) {
    order.sort((a, b) => d3.ascending(spread[a], spread[b]));
    let error = 0;
    for (let i = 1; i < spread.length; i++) {
      const gap = spread[order[i]] - spread[order[i - 1]];
      if (gap >= separation) continue;
      const shift = (separation - gap) / 2;
      error = Math.max(error, shift);
      spread[order[i - 1]] -= shift;
      spread[order[i]] += shift;
    }
    if (error < 0.1) break;
  }
  return spread;
}

export default function SurvivalRates({ data = DEMO, width }: { data?: Data; width: number }) {
  const height = Math.round(width * 0.62);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;
  const showNames = width >= NAME_LABEL_MIN_WIDTH;

  const x = useMemo(
    () =>
      d3
        .scalePoint<string>()
        .domain(data.steps)
        .range([0, innerWidth])
        .padding(0.5),
    [data, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain(d3.extent(data.conditions.flatMap((c) => c.values)) as [number, number])
        .range([innerHeight, 0]),
    [data, innerHeight]
  );

  const paths = useMemo(() => {
    const line = d3
      .line<number>()
      .x((_, i) => x(data.steps[i]) ?? 0)
      .y((value) => y(value));
    return data.conditions.map(({ name, values }) => ({ name, d: line(values) ?? '' }));
  }, [data, x, y]);

  // One dodged label column per step: the value alone in the middle, name + value at the edges.
  const columns = useMemo(
    () =>
      data.steps.map((step, stepIndex) => {
        const entries = data.conditions.map(({ name, values }) => ({ name, value: values[stepIndex] }));
        const dodged = dodge(entries.map((entry) => y(entry.value)));
        return {
          step,
          x: x(step) ?? 0,
          labels: entries.map((entry, i) => ({ ...entry, y: dodged[i] ?? 0 }))
        };
      }),
    [data, x, y]
  );

  if (width === 0) return null;

  // Names only ride the outer columns, and only when the margins can hold them.
  const edge = (step: string): 'left' | 'right' | null => {
    if (!showNames) return null;
    if (step === data.steps[0]) return 'left';
    return step === data.steps[data.steps.length - 1] ? 'right' : null;
  };

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={`Slope chart of survival rates for twelve fictional conditions across 5, 10, 15 and 20 year horizons. ${CAPTION}`}
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <g className="axis" textAnchor="middle">
          {columns.map((column) => (
            <g key={column.step} transform={`translate(${column.x},0)`}>
              <text y={-24}>{column.step}</text>
              <line y1={-18} y2={-10} />
            </g>
          ))}
        </g>

        <g fill="none" stroke="var(--muted)" strokeWidth={1} strokeOpacity={0.65}>
          {paths.map((path) => (
            <path key={path.name} d={path.d}>
              <title>{path.name}</title>
            </path>
          ))}
        </g>

        {columns.map((column) => {
          const side = edge(column.step);
          return (
            <g
              key={column.step}
              fontSize={11}
              fill="var(--text)"
              stroke="var(--bg)"
              strokeWidth={4}
              paintOrder="stroke"
              textAnchor={side === 'left' ? 'end' : side === 'right' ? 'start' : 'middle'}
            >
              {column.labels.map((label) => (
                <text
                  key={label.name}
                  x={column.x + (side === 'left' ? -LABEL_GAP : side === 'right' ? LABEL_GAP : 0)}
                  y={label.y}
                  dy="0.35em"
                >
                  {side === 'left'
                    ? `${label.name} ${formatValue(label.value)}`
                    : side === 'right'
                      ? `${formatValue(label.value)} ${label.name}`
                      : formatValue(label.value)}
                </text>
              ))}
            </g>
          );
        })}
      </g>

      <text
        x={width / 2}
        y={height - 10}
        textAnchor="middle"
        fontSize={11}
        fill="var(--muted)"
      >
        {width >= NAME_LABEL_MIN_WIDTH ? CAPTION : 'Illustrative synthetic data.'}
      </text>
    </svg>
  );
}
